class OrderRetention {
  OrderRetention(this.ditto);

  final Ditto ditto;
  SyncSubscription? _subscription;

  String _cutoff() => DateTime.now()
      .toUtc()
      .subtract(const Duration(days: 7))
      .toIso8601String();

  /// 起動時に一度呼び出す（ditto.sync.start() の前）。
